from collections import Counter
def boxes(g):
    seen=set(); res={}
    for r in range(len(g)):
        for c in range(len(g[0])):
            v=g[r][c]
            if v and (r,c) not in seen:
                stack=[(r,c)]; comp=[]
                while stack:
                    y,x=stack.pop()
                    if (y,x) in seen or g[y][x]!=v: continue
                    seen.add((y,x)); comp.append((y,x))
                    for dy in(-1,0,1):
                        for dx in(-1,0,1):
                            ny,nx=y+dy,x+dx
                            if 0<=ny<len(g) and 0<=nx<len(g[0]) and g[ny][nx]==v and (ny,nx) not in seen:
                                stack.append((ny,nx))
                ys=[p[0] for p in comp]; xs=[p[1] for p in comp]
                res[v]=(min(ys),max(ys),min(xs),max(xs),len(comp))
    return res
