def transform(g):
    g=[row[:] for row in g]; H,W=len(g),len(g[0])
    bycolor={}
    for r in range(H):
        for c in range(W):
            if g[r][c]: bycolor.setdefault(g[r][c],set()).add((r,c))
    info={}
    for v,cs in bycolor.items():
        r0=min(r for r,_ in cs); r1=max(r for r,_ in cs)
        c0=min(c for _,c in cs); c1=max(c for _,c in cs)
        info[v]=(r0,r1,c0,c1,len(cs),2*(r1-r0+1)+2*(c1-c0+1)-4)
    tv=None
    for v,(r0,r1,c0,c1,n,per) in info.items():
        if n!=per: tv=v; break
    tr0,tr1,tc0,tc1,tn,tper=info[tv]
    th,tw=tr1-tr0+1,tc1-tc0+1
    rel=sorted((r-tr0,c-tc0) for r,c in bycolor[tv])
    out=[row[:] for row in g]
    for v,cs in bycolor.items():
        if v==tv: continue
        r0,r1,c0,c1,n,per=info[v]
        if r1-r0+1==th and c1-c0+1==tw and n==per:
            for dr,dc in rel: out[r0+dr][c0+dc]=v
        else:
            for r,c in cs: out[r][c]=0
    return out
